import{_ as a,o as l,c as t,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"比尔·蔡尔德","description":"","frontmatter":{"title":"比尔·蔡尔德","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/比尔·蔡尔德.md","filePath":"04_people/比尔·蔡尔德.md"}'),i={name:"04_people/比尔·蔡尔德.md"};function o(s,e,n,h,_,d){return l(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="比尔·蔡尔德-bill-child" tabindex="-1">比尔·蔡尔德（Bill Child） <a class="header-anchor" href="#比尔·蔡尔德-bill-child" aria-label="Permalink to &quot;比尔·蔡尔德（Bill Child）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：R.C.威利家居（R.C. Willey）CEO</li><li><strong>与巴菲特关系</strong>：威利家居被伯克希尔收购后的核心高管</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>比尔·蔡尔德是R.C.威利家居的长期领导者。R.C.威利家居创立于1954年，总部位于犹他州盐湖城，是美国西部知名的家居零售商。蔡尔德带领威利家居从一家地方性家具店逐步发展成为区域龙头零售商，以仓储式销售模式著称。在他的领导下，威利家居建立了强大的竞争优势，在犹他州及周边市场占据主导地位。该公司以&quot;天天低价&quot;的定价策略和高效的运营模式著称，成为伯克希尔旗下重要的零售业务之一。威利家居的创始家族与蔡尔德家族长期合作，共同推动了公司的持续增长。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1954年</strong>：R.C.威利家居创立，为公司后续发展奠定基础</li><li><strong>1995年</strong>：伯克希尔·哈撒韦收购威利家居，蔡尔德继续担任CEO</li><li><strong>20世纪末</strong>：在威利家居扩张期间，蔡尔德主导了在内华达州、爱达荷州等地的市场拓展</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=比尔·蔡尔德在1997年股东信中的原话">1997年：完整翻译|/01_letters/1997年/翻译</a></li><li><a href="/search.html?q=比尔·蔡尔德在1995年股东信中的原话">1995年：完整翻译|/01_letters/1995年/翻译</a></li></ul>',11)])])}const u=a(i,[["render",o]]);export{p as __pageData,u as default};
